/** code → constant name (`-185` → `"ERR__TIMED_OUT"`). */
export const ERROR_NAMES: Readonly<Record<number, string>> = /* @__PURE__ */ (() => {
  const out: Record<number, string> = {};
  for (const [name, code] of Object.entries(ERROR_CODES)) {
    // The v2.15.0 table has no duplicate values, but keep "first wins" so that
    // if librdkafka later adds aliases, the earlier-declared name still wins.
    if (out[code] === undefined) out[code] = name;
  }
  return Object.freeze(out);
})();

/** Boundary of librdkafka's internal error range: code <= -100 is a "local" error. */
const LOCAL_ERR_MAX = ERROR_CODES.ERR__END;

/** Is this code a client-internal error (not one returned by the broker)? */
export function isLocalError(code: number): boolean {
  return code <= LOCAL_ERR_MAX;
}

/** Constant name of an `rd_kafka_resp_err_t`, or `undefined` when unknown. */
export function errorName(code: number): string | undefined {
  return ERROR_NAMES[code];
}

/** Human-readable description of an `rd_kafka_resp_err_t`. */
export function errorDescription(code: number): string {
  return ERROR_DESCRIPTIONS.get(code) ?? ERROR_NAMES[code] ?? `Unknown error ${code}`;
}

/* ========================================================================== */
/* LibrdKafkaError                                                             */
/* ========================================================================== */

/**
 * - `"kafka"`  — error returned by the broker (code >= -100)
 * - `"local"`  — librdkafka-internal error (code <= -100), matching upstream
 * - `"shim"`   — C shim layer error (`BRK_ERR_*`), NOT a librdkafka code
 */
export type ErrorOrigin = "local" | "kafka" | "shim";

export interface LibrdKafkaErrorInit {
  code?: number;
  origin?: ErrorOrigin;
  isFatal?: boolean;
  isRetriable?: boolean;
  isTxnRequiresAbort?: boolean;
  /** Extra debugging info (name of the FFI function being called…). */
  context?: string;
}

/**
 * Mirrors confluent-kafka-javascript's `LibrdKafkaError`:
 * `{ message, code, errno, origin, isFatal, isRetriable, isTxnRequiresAbort }`.
 */
export class LibrdKafkaError extends Error {
  override readonly name: string = "LibrdKafkaError";
  readonly code: number;
  /** Alias of `code` (upstream exposes both). */
  readonly errno: number;
  readonly origin: ErrorOrigin;
  readonly isFatal: boolean;
  readonly isRetriable: boolean;
  readonly isTxnRequiresAbort: boolean;
  readonly context: string | undefined;

  constructor(message: string, init: LibrdKafkaErrorInit = {}) {
    super(message);
    this.code = init.code ?? ERROR_CODES.ERR_UNKNOWN;
    this.errno = this.code;
    this.origin = init.origin ?? (isLocalError(this.code) ? "local" : "kafka");
    this.isFatal = init.isFatal ?? this.code === ERROR_CODES.ERR__FATAL;
    this.isRetriable = init.isRetriable ?? false;
    this.isTxnRequiresAbort = init.isTxnRequiresAbort ?? false;
    this.context = init.context;
  }

  /** Builds from a plain `rd_kafka_resp_err_t`. */
  static fromKafkaCode(
    code: number,
    message?: string,
    init: Omit<LibrdKafkaErrorInit, "code"> = {},
  ): LibrdKafkaError {
    return new LibrdKafkaError(message || errorDescription(code), { ...init, code });
  }

  /** Builds from a shim-layer error code (`BRK_ERR_*`, range -99..-1). */
  static fromShimCode(brkCode: number, message?: string, context?: string): LibrdKafkaError {
    const label = BRK_ERR_NAMES[brkCode] ?? `BRK_ERR(${brkCode})`;
    return new LibrdKafkaError(message || `bun-rdkafka native shim: ${label}`, {
      code: brkCode,
      origin: "shim",
      ...(context === undefined ? {} : { context }),
    });
  }

  /**
   * Decodes a `brk_*` function's negative return value into an error.
   * Returns `undefined` when `ret >= 0` (success).
   */
  static fromReturn(
    ret: number,
    context?: string,
    message?: string,
  ): LibrdKafkaError | undefined {
    if (ret >= 0) return undefined;
    if (isKafkaErr(ret)) {
      const code = kafkaErrOf(ret);
      return new LibrdKafkaError(message || errorDescription(code), {
        code,
        ...(context === undefined ? {} : { context }),
      });
    }
    if (isShimErr(ret)) return LibrdKafkaError.fromShimCode(ret, message, context);
    return new LibrdKafkaError(
      message || `bun-rdkafka: invalid return value from native: ${ret}`,
      {
        code: ret,
        origin: "shim",
        ...(context === undefined ? {} : { context }),
      },
    );
  }

  /**
   * Builds an error from `ret` + the errstr written by the shim.
   *
   * The shim appends `[txn-requires-abort]` / `[retriable]` markers to the
   * errstr for the transaction group (librdkafka returns an `rd_kafka_error_t`
   * with these two flags, which the POD ABI cannot carry) — see
   * `native/src/shim_producer.c`.
   * TODO(M4): drop this parsing if the shim switches to flag bits in ret.
   */
  static fromErrstr(ret: number, context: string, errstr: string): LibrdKafkaError {
    const parsed = parseErrstrFlags(errstr);
    const base = LibrdKafkaError.fromReturn(
      ret,
      context,
      parsed.message ? `${context}: ${parsed.message}` : undefined,
    );
    if (!base) {
      throw new TypeError(`fromErrstr() called with a non-error ret: ${ret}`);
    }
    return new LibrdKafkaError(base.message, {
      code: base.code,
      origin: base.origin,
      isFatal: base.isFatal,
      isRetriable: parsed.isRetriable,
      isTxnRequiresAbort: parsed.isTxnRequiresAbort,
      context,
    });
  }

  toJSON(): Record<string, unknown> {
    return {
      name: this.name,
      message: this.message,
      code: this.code,
      errno: this.errno,
      origin: this.origin,
      isFatal: this.isFatal,
      isRetriable: this.isRetriable,
      isTxnRequiresAbort: this.isTxnRequiresAbort,
    };
  }
}

/* ========================================================================== */
/* Transaction flags embedded in the errstr (side contract with shim_producer.c) */
/* ========================================================================== */

/** Marker the shim appends to the errstr on `rd_kafka_error_txn_requires_abort()`. */
export const ERRSTR_FLAG_TXN_REQUIRES_ABORT = "[txn-requires-abort]";
/** Marker the shim appends to the errstr on `rd_kafka_error_is_retriable()`. */
export const ERRSTR_FLAG_RETRIABLE = "[retriable]";

export interface ParsedErrstr {
  /** errstr with markers stripped and trimmed. */
  message: string;
  isRetriable: boolean;
  isTxnRequiresAbort: boolean;
}

/** Splits the `[retriable]` / `[txn-requires-abort]` flags out of the shim's errstr. */
export function parseErrstrFlags(errstr: string): ParsedErrstr {
  let message = errstr;
  const isTxnRequiresAbort = message.includes(ERRSTR_FLAG_TXN_REQUIRES_ABORT);
  const isRetriable = message.includes(ERRSTR_FLAG_RETRIABLE);
  if (isTxnRequiresAbort) message = message.split(ERRSTR_FLAG_TXN_REQUIRES_ABORT).join("");
  if (isRetriable) message = message.split(ERRSTR_FLAG_RETRIABLE).join("");
  return { message: message.trim(), isRetriable, isTxnRequiresAbort };
}

/** Throws if `ret < 0`, otherwise returns `ret`. */
export function throwOnError(ret: number, context?: string, message?: string): number {
  const err = LibrdKafkaError.fromReturn(ret, context, message);
  if (err) throw err;
  return ret;
}

/** Same as {@link LibrdKafkaError.fromReturn} — a short name for the core layer. */
export function decodeReturn(
  ret: number,
  context?: string,
  message?: string,
): LibrdKafkaError | undefined {
  return LibrdKafkaError.fromReturn(ret, context, message);
}
